+    await book(24, 25);
+    const response = await book(23.5, 24.5, 'Overlap from the left');
+    expect(response.statusCode).toBe(409);
+    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
+  });
+
+  it('rejects updating a booking into a slot occupied by another booking', async () => {
+    const first = await book(24, 25);
+    const second = await book(30, 31, 'Retro');
+    const response = await app.inject({
+      method: 'PATCH',
+      url: `/bookings/${second.json().id}`,
+      payload: { startsAt: inHours(24.5), endsAt: inHours(25.5) },
+    });
+    expect(response.statusCode).toBe(409);
+    expect(response.json().error.details.conflictingBookingId).toBe(first.json().id);
+  });
+
+  it('allows updating a booking to a time that does not conflict with itself', async () => {
+    const created = await book(24, 25);
+    const response = await app.inject({
+      method: 'PATCH',
+      url: `/bookings/${created.json().id}`,
+      payload: { startsAt: inHours(24.25), endsAt: inHours(25.25) },
+    });
+    expect(response.statusCode).toBe(200);
+  });
+
+  describe('availability', () => {
+    it('reports the whole window as free when there are no bookings', async () => {
+      const from = inHours(0);
+      const to = inHours(10);
+      const response = await app.inject({
+        method: 'GET',
+        url: `/bookings/availability?roomId=${roomId}&from=${from}&to=${to}`,
+      });
+      expect(response.statusCode).toBe(200);
+      const body = response.json();
+      expect(body.freeSlots).toEqual([{ startsAt: from, endsAt: to }]);
+    });
+
+    it('splits the window around an active booking', async () => {
+      const from = inHours(0);
+      const to = inHours(10);
+      const busy = await book(2, 3);
+      const busyStart = busy.json().startsAt;
+      const busyEnd = busy.json().endsAt;
+      const response = await app.inject({
+        method: 'GET',
+        url: `/bookings/availability?roomId=${roomId}&from=${from}&to=${to}`,
+      });
+      const body = response.json();
+      expect(body.freeSlots).toEqual([
+        { startsAt: from, endsAt: busyStart },
+        { startsAt: busyEnd, endsAt: to },
+      ]);
+    });
+
+    it('ignores a cancelled booking when computing free slots', async () => {
+      const from = inHours(0);
+      const to = inHours(10);
+      const created = await book(2, 3);
+      await app.inject({ method: 'POST', url: `/bookings/${created.json().id}/cancel` });
+      const response = await app.inject({
+        method: 'GET',
+        url: `/bookings/availability?roomId=${roomId}&from=${from}&to=${to}`,
+      });
+      expect(response.json().freeSlots).toEqual([{ startsAt: from, endsAt: to }]);
+    });
+
+    it('answers 404 for a room that does not exist', async () => {
+      const response = await app.inject({
+        method: 'GET',
+        url: `/bookings/availability?roomId=missing&from=${inHours(0)}&to=${inHours(10)}`,
+      });
+      expect(response.statusCode).toBe(404);
+    });
+
+    it('rejects a window where to is not after from', async () => {
+      const response = await app.inject({
+        method: 'GET',
+        url: `/bookings/availability?roomId=${roomId}&from=${inHours(10)}&to=${inHours(0)}`,
+      });
+      expect(response.statusCode).toBe(400);
+      expect(response.json().error.code).toBe('VALIDATION_ERROR');
+    });
+  });
 });

